const e={count:100,settings:{level:"Mixed",grammarFocus:["Mixed Grammar"],topics:["General"],lengthWords:[4,15],targetLang:"es"},sentences:[{id:"1",text:"This is my book, and that one is yours.",translation:"Este es mi libro y ese es el tuyo.",hint:{sentenceWithBlank:"This is my book, and that one is [____].",options:[{text:"yours",isCorrect:!0,explanation:"Forma absoluta del posesivo: no necesita un sustantivo detrás."},{text:"your",isCorrect:!1,explanation:"Es un adjetivo posesivo: exige un sustantivo detrás (your book)."},{text:"you",isCorrect:!1,explanation:"Es un pronombre personal, no un posesivo."}]},tense:"Present Simple",topic:"General",lengthWords:9},{id:"2",text:"He gave her his car because hers was broken.",translation:"Él le dio su coche porque el de ella estaba estropeado.",hint:{sentenceWithBlank:"He gave her his car because [____] was broken.",options:[{text:"hers",isCorrect:!0,explanation:"Forma absoluta del posesivo: sustituye a 'her car' sin repetir el sustantivo."},{text:"her",isCorrect:!1,explanation:"Adjetivo posesivo: necesita un sustantivo detrás (her car)."},{text:"she",isCorrect:!1,explanation:"Pronombre personal (ella); no expresa posesión."}]},tense:"Past Simple",topic:"General",lengthWords:9},{id:"3",text:"We did it ourselves without any help.",translation:"Lo hicimos nosotros mismos, sin ninguna ayuda.",hint:{sentenceWithBlank:"We [____] [____] ourselves without any help.",options:[{text:"did it",isCorrect:!0,explanation:"Forma correcta de pasado del verbo 'do' junto con el pronombre 'it'."},{text:"do it",isCorrect:!1,explanation:"Verbo en presente; la frase habla del pasado."},{text:"made it",isCorrect:!1,explanation:"'Make' significa crear o fabricar, mientras que 'do' es realizar una acción."}]},tense:"Past Simple",topic:"General",lengthWords:7},{id:"4",text:"Is there anybody in the office?",translation:"¿Hay alguien en la oficina?",hint:{sentenceWithBlank:"[____] there anybody in the office?",options:[{text:"Is",isCorrect:!0,explanation:"En la estructura 'there is/are', con 'anybody' se usa el singular 'is'."},{text:"Are",isCorrect:!1,explanation:"Se usa con sujetos en plural."},{text:"Does",isCorrect:!1,explanation:"No se emplea en la estructura 'there is/are'."}]},tense:"Present Simple",topic:"Workplace",lengthWords:6},{id:"5",text:"Nobody told me about the changes.",translation:"Nadie me habló de los cambios.",hint:{sentenceWithBlank:"Nobody [____] me about the changes.",options:[{text:"told",isCorrect:!0,explanation:"Verbo en afirmativo en Past Simple: la negación ya está en 'Nobody'."},{text:"didn't tell",isCorrect:!1,explanation:"El inglés no admite la doble negación (Nobody + didn't)."},{text:"said",isCorrect:!1,explanation:"'Say' no lleva un complemento de persona (me) sin la preposición 'to'."}]},tense:"Past Simple",topic:"General",lengthWords:6},{id:"6",text:"This is the building whose roof was damaged.",translation:"Este es el edificio cuyo tejado resultó dañado.",hint:{sentenceWithBlank:"This is the building [____] roof was damaged.",options:[{text:"whose",isCorrect:!0,explanation:"Pronombre relativo de posesión: equivale a 'cuyo, cuya'."},{text:"who",isCorrect:!1,explanation:"'Who' significa 'quién' y no expresa posesión."},{text:"which",isCorrect:!1,explanation:"'Which' (que, el cual) no indica posesión."}]},tense:"Passive Voice",topic:"General",lengthWords:8},{id:"7",text:"Give it to him, not to them.",translation:"Dáselo a él, no a ellos.",hint:{sentenceWithBlank:"Give it to him, not to [____].",options:[{text:"them",isCorrect:!0,explanation:"Caso objeto del pronombre 'they' (les, a ellos)."},{text:"their",isCorrect:!1,explanation:"Adjetivo posesivo (su, de ellos); exige un sustantivo detrás."},{text:"they",isCorrect:!1,explanation:"Caso sujeto (ellos); se coloca delante del verbo."}]},tense:"Imperative",topic:"General",lengthWords:7},{id:"8",text:"Both of them are busy right now.",translation:"Los dos están ocupados ahora mismo.",hint:{sentenceWithBlank:"[____] of them are busy right now.",options:[{text:"Both",isCorrect:!0,explanation:"Significa 'ambos', los dos a la vez."},{text:"All",isCorrect:!1,explanation:"'All' (todos) se usa a partir de tres personas o cosas."},{text:"Either",isCorrect:!1,explanation:"'Either' (cualquiera de los dos) exige el verbo en singular."}]},tense:"Present Simple",topic:"General",lengthWords:7},{id:"9",text:"Neither of the options is perfect.",translation:"Ninguna de las dos opciones es perfecta.",hint:{sentenceWithBlank:"[____] of the options is perfect.",options:[{text:"Neither",isCorrect:!0,explanation:"Significa 'ninguno de los dos'."},{text:"None",isCorrect:!1,explanation:"'None' se usa cuando hay tres elementos o más."},{text:"Both",isCorrect:!1,explanation:"Significa 'ambos' y pide el verbo en plural (are)."}]},tense:"Present Simple",topic:"General",lengthWords:6},{id:"10",text:"Each component has its own function.",translation:"Cada componente tiene su propia función.",hint:{sentenceWithBlank:"Each component [____] its own function.",options:[{text:"has",isCorrect:!0,explanation:"'Each' (cada) concuerda con el verbo en singular."},{text:"have",isCorrect:!1,explanation:"Es la forma de plural."},{text:"having",isCorrect:!1,explanation:"Es un gerundio o participio; aquí hace falta un verbo conjugado."}]},tense:"Present Simple",topic:"General",lengthWords:6},{id:"11",text:"She usually goes to work by bus, but today she is driving.",translation:"Normalmente va al trabajo en autobús, pero hoy va en coche.",hint:{sentenceWithBlank:"She usually goes to work by bus, but today she [____] [____].",options:[{text:"is driving",isCorrect:!0,explanation:"El Present Continuous expresa una acción temporal que ocurre precisamente hoy."},{text:"drives",isCorrect:!1,explanation:"El Present Simple sirve para acciones habituales (usually)."},{text:"driving",isCorrect:!1,explanation:"Falta el verbo auxiliar 'is'."}]},tense:"Present Continuous",topic:"Daily Life",lengthWords:12},{id:"12",text:"Water boils at 100 degrees Celsius.",translation:"El agua hierve a 100 grados Celsius.",hint:{sentenceWithBlank:"Water [____] at 100 degrees Celsius.",options:[{text:"boils",isCorrect:!0,explanation:"El Present Simple se usa para hechos científicos y verdades generales."},{text:"is boiling",isCorrect:!1,explanation:"El Present Continuous describe algo que pasa ahora mismo, no un hecho general."},{text:"boiled",isCorrect:!1,explanation:"El Past Simple sirve para acciones del pasado."}]},tense:"Present Simple",topic:"Science",lengthWords:6},{id:"13",text:"Does he know where the keys are?",translation:"¿Sabe él dónde están las llaves?",hint:{sentenceWithBlank:"[____] he know where the keys are?",options:[{text:"Does",isCorrect:!0,explanation:"Auxiliar del Present Simple para he, she, it."},{text:"Do",isCorrect:!1,explanation:"Se usa con I, you, we, they."},{text:"Is",isCorrect:!1,explanation:"El verbo 'to be' no funciona como auxiliar junto al verbo léxico 'know'."}]},tense:"Present Simple",topic:"Daily Life",lengthWords:7},{id:"14",text:"Why didn't you call me yesterday?",translation:"¿Por qué no me llamaste ayer?",hint:{sentenceWithBlank:"Why [____] you call me yesterday?",options:[{text:"didn't",isCorrect:!0,explanation:"Auxiliar de la pregunta negativa en Past Simple."},{text:"don't",isCorrect:!1,explanation:"Es presente, pero la frase lleva el marcador temporal 'yesterday'."},{text:"weren't",isCorrect:!1,explanation:"El verbo 'to be' no acompaña a un verbo léxico (call) en los tiempos simples."}]},tense:"Past Simple",topic:"General",lengthWords:6},{id:"15",text:"I saw a great movie last weekend.",translation:"Vi una película estupenda el fin de semana pasado.",hint:{sentenceWithBlank:"I [____] a great movie last weekend.",options:[{text:"saw",isCorrect:!0,explanation:"Past Simple (segunda forma de 'see') para una acción terminada en el pasado (last weekend)."},{text:"see",isCorrect:!1,explanation:"Es presente y no encaja con 'last weekend'."},{text:"have seen",isCorrect:!1,explanation:"El Present Perfect no se usa con una referencia temporal pasada concreta."}]},tense:"Past Simple",topic:"Entertainment",lengthWords:7},{id:"16",text:"They didn't arrive on time because of the traffic.",translation:"No llegaron a tiempo por culpa del tráfico.",hint:{sentenceWithBlank:"They didn't arrive on time [____] of the traffic.",options:[{text:"because",isCorrect:!0,explanation:"'Because of' (a causa de) va seguido de un sustantivo."},{text:"why",isCorrect:!1,explanation:"Significa 'por qué' y es una palabra interrogativa."},{text:"as",isCorrect:!1,explanation:"'As' (ya que) exige detrás una oración completa con sujeto y verbo."}]},tense:"Past Simple",topic:"Travel",lengthWords:9},{id:"17",text:"What will you do if they reject the plan?",translation:"¿Qué harás si rechazan el plan?",hint:{sentenceWithBlank:"What [____] you do if they reject the plan?",options:[{text:"will",isCorrect:!0,explanation:"Future Simple en la oración principal del condicional de tipo 1 (First Conditional)."},{text:"would",isCorrect:!1,explanation:"Pertenece al condicional de tipo 2 (situación irreal)."},{text:"do",isCorrect:!1,explanation:"Daría una pregunta en presente: '¿Qué haces normalmente?'."}]},tense:"Future Simple",topic:"Workplace",lengthWords:9},{id:"18",text:"I think it will be a sunny day.",translation:"Creo que hará un día soleado.",hint:{sentenceWithBlank:"I think it [____] [____] a sunny day.",options:[{text:"will be",isCorrect:!0,explanation:"Future Simple para predicciones y opiniones personales (I think)."},{text:"is being",isCorrect:!1,explanation:"Indica un comportamiento pasajero en este momento; no encaja aquí."},{text:"will",isCorrect:!1,explanation:"Falta el verbo principal 'be'."}]},tense:"Future Simple",topic:"General",lengthWords:8},{id:"19",text:"Are you going to update the layout this evening?",translation:"¿Vas a actualizar el diseño esta tarde?",hint:{sentenceWithBlank:"Are you [____] [____] update the layout this evening?",options:[{text:"going to",isCorrect:!0,explanation:"La estructura 'to be going to' expresa planes e intenciones."},{text:"will to",isCorrect:!1,explanation:"Detrás de 'will' nunca se pone la partícula 'to'."},{text:"want to",isCorrect:!1,explanation:"Se traduciría como '¿Quieres...?' y no como '¿Vas a...?'."}]},tense:"Future (going to)",topic:"IT",lengthWords:9},{id:"20",text:"The train leaves at 9 PM tonight.",translation:"El tren sale hoy a las nueve de la noche.",hint:{sentenceWithBlank:"The train [____] at 9 PM tonight.",options:[{text:"leaves",isCorrect:!0,explanation:"El Present Simple se usa para horarios de transporte, aunque se refiera al futuro."},{text:"will leave",isCorrect:!1,explanation:"Con los horarios establecidos se prefiere el Present Simple."},{text:"is leaving",isCorrect:!1,explanation:"Sirve para citas y planes personales, no para un horario oficial."}]},tense:"Present Simple",topic:"Travel",lengthWords:7},{id:"21",text:"How often do you practice your English?",translation:"¿Con qué frecuencia practicas tu inglés?",hint:{sentenceWithBlank:"How [____] do you practice your English?",options:[{text:"often",isCorrect:!0,explanation:"'How often' (con qué frecuencia) pregunta por la regularidad."},{text:"many",isCorrect:!1,explanation:"Significa 'cuántos' y acompaña a sustantivos contables."},{text:"much",isCorrect:!1,explanation:"Significa 'cuánto' y acompaña a sustantivos incontables."}]},tense:"Present Simple",topic:"Education",lengthWords:7},{id:"22",text:"Who wrote this article?",translation:"¿Quién escribió este artículo?",hint:{sentenceWithBlank:"Who [____] this article?",options:[{text:"wrote",isCorrect:!0,explanation:"En las preguntas dirigidas al sujeto no se usa el auxiliar 'did': el orden es el de una afirmación."},{text:"did write",isCorrect:!1,explanation:"Construcción incorrecta en una pregunta dirigida al sujeto (Who)."},{text:"written",isCorrect:!1,explanation:"Es el participio y necesita el auxiliar have/has."}]},tense:"Past Simple",topic:"General",lengthWords:4},{id:"23",text:"Who did you invite to the presentation?",translation:"¿A quién invitaste a la presentación?",hint:{sentenceWithBlank:"Who [____] you invite to the presentation?",options:[{text:"did",isCorrect:!0,explanation:"Auxiliar de la pregunta en Past Simple (pregunta al complemento: '¿a quién?')."},{text:"do",isCorrect:!1,explanation:"Es presente: 'a quién invitas normalmente'."},{text:"were",isCorrect:!1,explanation:"El verbo 'to be' no acompaña al verbo léxico 'invite' en un tiempo simple."}]},tense:"Past Simple",topic:"Workplace",lengthWords:7},{id:"24",text:"There used to be a cinema here.",translation:"Antes aquí había un cine.",hint:{sentenceWithBlank:"There [____] to be a cinema here.",options:[{text:"used",isCorrect:!0,explanation:"La estructura 'used to' habla de algo que existía antes y ya no existe."},{text:"use",isCorrect:!1,explanation:"Hace falta la forma de pasado (used)."},{text:"was",isCorrect:!1,explanation:"Detrás de 'was' no puede ir el infinitivo 'to be'."}]},tense:"Past Habit",topic:"General",lengthWords:7},{id:"25",text:"I am used to waking up early.",translation:"Estoy acostumbrado a levantarme temprano.",hint:{sentenceWithBlank:"I am [____] [____] waking up early.",options:[{text:"used to",isCorrect:!0,explanation:"La estructura 'to be used to + V-ing' expresa una costumbre ya adquirida."},{text:"use to",isCorrect:!1,explanation:"Para hablar de una costumbre hace falta la forma 'used'."},{text:"used",isCorrect:!1,explanation:"Falta la preposición 'to', obligatoria en esta estructura."}]},tense:"Present Habit",topic:"Daily Life",lengthWords:7},{id:"26",text:"Look! It is snowing outside.",translation:"¡Mira! Está nevando fuera.",hint:{sentenceWithBlank:"Look! It [____] outside.",options:[{text:"is snowing",isCorrect:!0,explanation:"El Present Continuous describe lo que ocurre justo ahora (lo señala '¡Look!')."},{text:"snows",isCorrect:!1,explanation:"El Present Simple expresa una acción habitual, no lo que pasa en este momento."},{text:"snowing",isCorrect:!1,explanation:"Falta el verbo auxiliar 'is'."}]},tense:"Present Continuous",topic:"Nature",lengthWords:5},{id:"27",text:"What were you doing when I called you?",translation:"¿Qué estabas haciendo cuando te llamé?",hint:{sentenceWithBlank:"What [____] you [____] when I called you?",options:[{text:"were / doing",isCorrect:!0,explanation:"El Past Continuous expresa una acción en desarrollo en el pasado interrumpida por otra (cuando llamé)."},{text:"did / do",isCorrect:!1,explanation:"El Past Simple sirve para acciones terminadas y sucesivas, no para un proceso."},{text:"are / doing",isCorrect:!1,explanation:"El Present Continuous se refiere al presente, pero aquí hablamos del pasado ('when I called')."}]},tense:"Past Continuous",topic:"General",lengthWords:8},{id:"28",text:"While she was cooking, he was reading a book.",translation:"Mientras ella cocinaba, él leía un libro.",hint:{sentenceWithBlank:"While she [____], he was reading a book.",options:[{text:"was cooking",isCorrect:!0,explanation:"El Past Continuous se usa para dos acciones simultáneas en desarrollo en el pasado."},{text:"cooked",isCorrect:!1,explanation:"El Past Simple indica una acción acabada, pero 'while' señala un proceso."},{text:"is cooking",isCorrect:!1,explanation:"La segunda parte está en pasado ('was reading'), así que la primera también debe estarlo."}]},tense:"Past Continuous",topic:"Daily Life",lengthWords:9},{id:"29",text:"I have already finished the first task.",translation:"Ya he terminado la primera tarea.",hint:{sentenceWithBlank:"I [____] already [____] the first task.",options:[{text:"have / finished",isCorrect:!0,explanation:"El Present Perfect expresa una acción acabada con resultado en el presente (marcador 'already')."},{text:"am / finishing",isCorrect:!1,explanation:"El Present Continuous diría que la acción sigue en curso, pero 'already' indica que ya está terminada."},{text:"had / finished",isCorrect:!1,explanation:"El Past Perfect haría falta si hubiera otra acción pasada de referencia."}]},tense:"Present Perfect",topic:"Workplace",lengthWords:7},{id:"30",text:"Have you ever been to London?",translation:"¿Has estado alguna vez en Londres?",hint:{sentenceWithBlank:"Have you [____] been to London?",options:[{text:"ever",isCorrect:!0,explanation:"'Ever' (alguna vez) es habitual en las preguntas de Present Perfect sobre experiencias."},{text:"never",isCorrect:!1,explanation:"'Never' significa 'nunca' y se usa en frases afirmativas con sentido negativo."},{text:"yet",isCorrect:!1,explanation:"'Yet' se coloca al final de la frase."}]},tense:"Present Perfect",topic:"Travel",lengthWords:6},{id:"31",text:"She has lived here since 2015.",translation:"Vive aquí desde 2015.",hint:{sentenceWithBlank:"She has lived here [____] 2015.",options:[{text:"since",isCorrect:!0,explanation:"'Since' señala el momento concreto en que empezó la acción."},{text:"for",isCorrect:!1,explanation:"'For' indica la duración de un periodo (for 5 years)."},{text:"from",isCorrect:!1,explanation:"'From' normalmente necesita su pareja: 'to' o 'until'."}]},tense:"Present Perfect",topic:"General",lengthWords:6},{id:"32",text:"We haven't seen each other for ages.",translation:"Hace siglos que no nos vemos.",hint:{sentenceWithBlank:"We [____] each other for ages.",options:[{text:"haven't seen",isCorrect:!0,explanation:"El Present Perfect expresa la ausencia de la acción desde el pasado hasta ahora ('for ages')."},{text:"didn't see",isCorrect:!1,explanation:"El Past Simple señala un periodo cerrado, pero aquí el periodo continúa hasta hoy."},{text:"don't see",isCorrect:!1,explanation:"El Present Simple describe acciones habituales, no un estado que dura desde entonces."}]},tense:"Present Perfect",topic:"General",lengthWords:7},{id:"33",text:"When I arrived, the meeting had already started.",translation:"Cuando llegué, la reunión ya había empezado.",hint:{sentenceWithBlank:"When I arrived, the meeting [____] already [____].",options:[{text:"had / started",isCorrect:!0,explanation:"El Past Perfect marca la acción terminada antes de otra acción pasada ('When I arrived')."},{text:"has / started",isCorrect:!1,explanation:"El Present Perfect no encaja si la acción de referencia está en pasado ('arrived')."},{text:"was / starting",isCorrect:!1,explanation:"Diría que la reunión estaba empezando, pero 'already' indica que ya había empezado."}]},tense:"Past Perfect",topic:"Workplace",lengthWords:8},{id:"34",text:"He realized he had lost his wallet.",translation:"Se dio cuenta de que había perdido la cartera.",hint:{sentenceWithBlank:"He realized he [____] his wallet.",options:[{text:"had lost",isCorrect:!0,explanation:"El Past Perfect expresa la acción (perder) anterior a otra acción pasada (darse cuenta)."},{text:"loses",isCorrect:!1,explanation:"El Present Simple no concuerda: la oración principal está en pasado."},{text:"has lost",isCorrect:!1,explanation:"El Present Perfect conecta con el presente, pero aquí la constatación ('realized') es pasada."}]},tense:"Past Perfect",topic:"General",lengthWords:7},{id:"35",text:"By next year, they will have completed the project.",translation:"Para el año que viene habrán terminado el proyecto.",hint:{sentenceWithBlank:"By next year, they [____] the project.",options:[{text:"will have completed",isCorrect:!0,explanation:"El Future Perfect indica una acción terminada antes de un momento futuro ('By next year')."},{text:"will complete",isCorrect:!1,explanation:"Expresa un hecho futuro, pero 'by' exige Future Perfect."},{text:"are completing",isCorrect:!1,explanation:"El Present Continuous habla de planes y no transmite la idea de acción acabada para esa fecha."}]},tense:"Future Perfect",topic:"Workplace",lengthWords:9},{id:"36",text:"I will be flying to Paris this time tomorrow.",translation:"Mañana a estas horas estaré volando a París.",hint:{sentenceWithBlank:"I [____] to Paris this time tomorrow.",options:[{text:"will be flying",isCorrect:!0,explanation:"El Future Continuous describe un proceso en marcha en un momento concreto del futuro ('this time tomorrow')."},{text:"will fly",isCorrect:!1,explanation:"El Future Simple expresa un hecho o una decisión, no un proceso en ese momento."},{text:"fly",isCorrect:!1,explanation:"El Present Simple valdría para un horario, pero aquí interesa el vuelo como proceso."}]},tense:"Future Continuous",topic:"Travel",lengthWords:9},{id:"37",text:"This is the best coffee I have ever tasted.",translation:"Es el mejor café que he probado en mi vida.",hint:{sentenceWithBlank:"This is the best coffee I have [____] tasted.",options:[{text:"ever",isCorrect:!0,explanation:"'Ever' habla de la experiencia vital, sobre todo tras un superlativo ('the best')."},{text:"never",isCorrect:!1,explanation:"'Never' cambiaría el sentido a 'nunca lo he probado'."},{text:"already",isCorrect:!1,explanation:"'Already' significa 'ya', que no encaja con la idea de 'el mejor de todos'."}]},tense:"Present Perfect",topic:"Daily Life",lengthWords:9},{id:"38",text:"It's the first time I have driven an electric car.",translation:"Es la primera vez que conduzco un coche eléctrico.",hint:{sentenceWithBlank:"It's the first time I [____] an electric car.",options:[{text:"have driven",isCorrect:!0,explanation:"La estructura 'It's the first time...' pide siempre Present Perfect."},{text:"drive",isCorrect:!1,explanation:"El Present Simple no sirve aquí, porque se habla de una experiencia."},{text:"drove",isCorrect:!1,explanation:"El Past Simple describe hechos cerrados, pero esta experiencia es relevante ahora."}]},tense:"Present Perfect",topic:"General",lengthWords:10},{id:"39",text:"She was tired because she had worked all night.",translation:"Estaba cansada porque había trabajado toda la noche.",hint:{sentenceWithBlank:"She was tired because she [____] all night.",options:[{text:"had worked",isCorrect:!0,explanation:"El Past Perfect explica la causa (había trabajado) de un estado pasado (estaba cansada)."},{text:"has worked",isCorrect:!1,explanation:"El Present Perfect no encaja: el resultado (estaba cansada) está en el pasado."},{text:"worked",isCorrect:!1,explanation:"El Past Simple sería posible, pero el Past Perfect marca mejor la anterioridad y la causa."}]},tense:"Past Perfect",topic:"Daily Life",lengthWords:9},{id:"40",text:"I had never seen such a beautiful sunset before.",translation:"Nunca había visto una puesta de sol tan bonita.",hint:{sentenceWithBlank:"I [____] seen such a beautiful sunset before.",options:[{text:"had never",isCorrect:!0,explanation:"El Past Perfect subraya que esa experiencia no existía hasta cierto momento del pasado."},{text:"have never",isCorrect:!1,explanation:"El Present Perfect apunta al presente, pero 'before' señala un punto del pasado."},{text:"did never",isCorrect:!1,explanation:"Construcción incorrecta (sería 'never saw', aunque aquí se necesita Past Perfect)."}]},tense:"Past Perfect",topic:"Nature",lengthWords:9},{id:"41",text:"I have been learning English for three years.",translation:"Llevo tres años estudiando inglés.",hint:{sentenceWithBlank:"I [____] English for three years.",options:[{text:"have been learning",isCorrect:!0,explanation:"El Present Perfect Continuous resalta la duración de una acción que empezó en el pasado y sigue ahora."},{text:"am learning",isCorrect:!1,explanation:"El Present Continuous no se combina con un periodo de tiempo ('for three years')."},{text:"learn",isCorrect:!1,explanation:"El Present Simple describe hechos, no un proceso que dura un tiempo determinado."}]},tense:"Present Perfect Continuous",topic:"Education",lengthWords:8},{id:"42",text:"Why are your hands dirty? — I've been fixing my bike.",translation:"¿Por qué tienes las manos sucias? — He estado arreglando la bici.",hint:{sentenceWithBlank:"Why are your hands dirty? — I've [____] my bike.",options:[{text:"been fixing",isCorrect:!0,explanation:"El Present Perfect Continuous explica un resultado visible ahora (las manos sucias) por un proceso reciente."},{text:"fixed",isCorrect:!1,explanation:"El Present Perfect subraya la finalización, pero aquí importa el proceso que dejó huella."},{text:"fixing",isCorrect:!1,explanation:"Falta 'been' para formar el Present Perfect Continuous."}]},tense:"Present Perfect Continuous",topic:"Daily Life",lengthWords:11},{id:"43",text:"It has been raining all day.",translation:"Lleva lloviendo todo el día.",hint:{sentenceWithBlank:"It [____] all day.",options:[{text:"has been raining",isCorrect:!0,explanation:"Present Perfect Continuous para una acción que dura desde el pasado hasta ahora ('all day')."},{text:"is raining",isCorrect:!1,explanation:"El Present Continuous se refiere al momento actual, sin idea de duración."},{text:"rains",isCorrect:!1,explanation:"El Present Simple diría que llueve en general, no de forma continua todo el día."}]},tense:"Present Perfect Continuous",topic:"Nature",lengthWords:6},{id:"44",text:"She had been waiting for two hours before the bus arrived.",translation:"Llevaba dos horas esperando cuando llegó el autobús.",hint:{sentenceWithBlank:"She [____] for two hours before the bus arrived.",options:[{text:"had been waiting",isCorrect:!0,explanation:"El Past Perfect Continuous expresa cuánto duró la acción antes de otro hecho pasado."},{text:"has been waiting",isCorrect:!1,explanation:"El Present Perfect Continuous mira al presente, pero la segunda acción ('arrived') es pasada."},{text:"was waiting",isCorrect:!1,explanation:"Con 'for' (duración) y otra acción pasada posterior se prefiere el Past Perfect Continuous."}]},tense:"Past Perfect Continuous",topic:"Travel",lengthWords:11},{id:"45",text:"They had been living there for five years when the company closed.",translation:"Llevaban cinco años viviendo allí cuando la empresa cerró.",hint:{sentenceWithBlank:"They [____] there for five years when the company closed.",options:[{text:"had been living",isCorrect:!0,explanation:"El Past Perfect Continuous indica cuánto tiempo duró la acción hasta cierto momento del pasado."},{text:"were living",isCorrect:!1,explanation:"El Past Continuous no se usa cuando se indica la duración ('for five years')."},{text:"have been living",isCorrect:!1,explanation:"Los hechos ocurren en el pasado ('closed'), así que hace falta un tiempo pasado."}]},tense:"Past Perfect Continuous",topic:"General",lengthWords:12},{id:"46",text:"His eyes were red because he had been staring at the screen for hours.",translation:"Tenía los ojos rojos porque llevaba horas mirando la pantalla.",hint:{sentenceWithBlank:"His eyes were red because he [____] at the screen for hours.",options:[{text:"had been staring",isCorrect:!0,explanation:"El Past Perfect Continuous describe el proceso prolongado que causó un estado en el pasado."},{text:"has been staring",isCorrect:!1,explanation:"La consecuencia ('were red') está en pasado, así que se necesita un tiempo pasado."},{text:"was staring",isCorrect:!1,explanation:"El Past Continuous no transmite la anterioridad ni la duración que provocó el resultado."}]},tense:"Past Perfect Continuous",topic:"Daily Life",lengthWords:14},{id:"47",text:"By midnight, I will have been working on this design for ten hours.",translation:"A medianoche llevaré diez horas trabajando en este diseño.",hint:{sentenceWithBlank:"By midnight, I [____] on this design for ten hours.",options:[{text:"will have been working",isCorrect:!0,explanation:"El Future Perfect Continuous indica cuánto tiempo llevará durando la acción en un momento futuro."},{text:"will work",isCorrect:!1,explanation:"El Future Simple no expresa la duración acumulada hasta un momento futuro."},{text:"will be working",isCorrect:!1,explanation:"El Future Continuous describe el proceso, pero no subraya su duración ('for ten hours')."}]},tense:"Future Perfect Continuous",topic:"Workplace",lengthWords:13},{id:"48",text:"How long have you been looking for a job?",translation:"¿Cuánto tiempo llevas buscando trabajo?",hint:{sentenceWithBlank:"How long [____] you [____] for a job?",options:[{text:"have / been looking",isCorrect:!0,explanation:"Las preguntas con 'How long' sobre acciones inacabadas piden Present Perfect Continuous."},{text:"are / looking",isCorrect:!1,explanation:"El Present Continuous pregunta por el momento actual ('¿qué buscas ahora?'), no por la duración."},{text:"do / look",isCorrect:!1,explanation:"El Present Simple no encaja, porque no se trata de una acción habitual."}]},tense:"Present Perfect Continuous",topic:"General",lengthWords:9},{id:"49",text:"We had been driving for miles before we realized we were lost.",translation:"Llevábamos kilómetros conduciendo cuando nos dimos cuenta de que estábamos perdidos.",hint:{sentenceWithBlank:"We [____] for miles before we realized we were lost.",options:[{text:"had been driving",isCorrect:!0,explanation:"Past Perfect Continuous para un proceso que duró hasta cierto hecho del pasado."},{text:"have been driving",isCorrect:!1,explanation:"Todos los hechos de la frase son pasados ('realized', 'were'), así que el Present Perfect no vale."},{text:"were driving",isCorrect:!1,explanation:"El Past Continuous no destaca la duración acumulada previa a la otra acción."}]},tense:"Past Perfect Continuous",topic:"Travel",lengthWords:12},{id:"50",text:"She has been running, so she is out of breath.",translation:"Ha estado corriendo, por eso está sin aliento.",hint:{sentenceWithBlank:"She [____], so she is out of breath.",options:[{text:"has been running",isCorrect:!0,explanation:"El Present Perfect Continuous explica el estado actual ('out of breath') por un proceso reciente."},{text:"is running",isCorrect:!1,explanation:"El Present Continuous significaría que está corriendo justo ahora."},{text:"ran",isCorrect:!1,explanation:"El Past Simple se centra en el hecho de correr; el Present Perfect Continuous conecta mejor el proceso con el resultado."}]},tense:"Present Perfect Continuous",topic:"General",lengthWords:10},{id:"51",text:"You must wear a seatbelt while driving.",translation:"Hay que llevar puesto el cinturón de seguridad mientras se conduce.",hint:{sentenceWithBlank:"You [____] wear a seatbelt while driving.",options:[{text:"must",isCorrect:!0,explanation:"'Must' expresa una obligación estricta o una norma."},{text:"have",isCorrect:!1,explanation:"Detrás de 'have' hace falta la partícula 'to' (have to)."},{text:"can",isCorrect:!1,explanation:"'Can' indica capacidad o posibilidad, y aquí se trata de una norma."}]},tense:"Modal Verbs",topic:"Travel",lengthWords:7},{id:"52",text:"You don't have to pay for the tickets; they are free.",translation:"No hace falta que pagues las entradas: son gratis.",hint:{sentenceWithBlank:"You [____] pay for the tickets; they are free.",options:[{text:"don't have to",isCorrect:!0,explanation:"'Don't have to' indica ausencia de necesidad (no es obligatorio)."},{text:"mustn't",isCorrect:!1,explanation:"'Mustn't' expresa una prohibición estricta (no se debe)."},{text:"shouldn't",isCorrect:!1,explanation:"'Shouldn't' es un consejo (no deberías), pero aquí solo se constata que no hay necesidad."}]},tense:"Modal Verbs",topic:"General",lengthWords:11},{id:"53",text:"You shouldn't eat so much fast food.",translation:"No deberías comer tanta comida rápida.",hint:{sentenceWithBlank:"You [____] eat so much fast food.",options:[{text:"shouldn't",isCorrect:!0,explanation:"'Shouldn't' se emplea para dar consejos (no deberías)."},{text:"don't have to",isCorrect:!1,explanation:"Significa 'no es obligatorio' y no sirve para dar un consejo."},{text:"can't",isCorrect:!1,explanation:"'Can't' expresa prohibición o imposibilidad."}]},tense:"Modal Verbs",topic:"Daily Life",lengthWords:7},{id:"54",text:"He might come to the meeting, but he isn't sure.",translation:"Puede que venga a la reunión, pero no está seguro.",hint:{sentenceWithBlank:"He [____] come to the meeting, but he isn't sure.",options:[{text:"might",isCorrect:!0,explanation:"'Might' expresa una posibilidad baja en el futuro."},{text:"must",isCorrect:!1,explanation:"'Must' indica seguridad u obligación."},{text:"can",isCorrect:!1,explanation:"'Can' no suele usarse para la probabilidad de un hecho futuro concreto."}]},tense:"Modal Verbs",topic:"Workplace",lengthWords:10},{id:"55",text:"May I borrow your pen for a moment?",translation:"¿Me prestas tu bolígrafo un momento?",hint:{sentenceWithBlank:"[____] I borrow your pen for a moment?",options:[{text:"May",isCorrect:!0,explanation:"'May' sirve para pedir permiso de forma cortés."},{text:"Must",isCorrect:!1,explanation:"'Must' expresa obligación, no una petición."},{text:"Should",isCorrect:!1,explanation:"'Should' se usa para pedir o dar consejo (¿debería...?)."}]},tense:"Modal Verbs",topic:"General",lengthWords:8},{id:"56",text:"She can't be at home; I saw her at the office five minutes ago.",translation:"No puede estar en casa: la vi en la oficina hace cinco minutos.",hint:{sentenceWithBlank:"She [____] be at home; I saw her at the office five minutes ago.",options:[{text:"can't",isCorrect:!0,explanation:"'Can't' expresa la certeza de que algo es imposible."},{text:"mustn't",isCorrect:!1,explanation:"'Mustn't' indica una prohibición estricta, no una deducción lógica."},{text:"might not",isCorrect:!1,explanation:"'Might not' solo expresa una posibilidad, pero aquí hay seguridad."}]},tense:"Modal Verbs",topic:"General",lengthWords:14},{id:"57",text:"He must have forgotten about our appointment.",translation:"Se le habrá olvidado nuestra cita.",hint:{sentenceWithBlank:"He [____] about our appointment.",options:[{text:"must have forgotten",isCorrect:!0,explanation:"'Must + have + participio' expresa una deducción segura sobre el pasado."},{text:"must forget",isCorrect:!1,explanation:"Se refiere al presente o al futuro."},{text:"should have forgotten",isCorrect:!1,explanation:"Significaría 'debería haberlo olvidado'."}]},tense:"Modal Verbs",topic:"General",lengthWords:7},{id:"58",text:"You should have told me the truth earlier.",translation:"Deberías haberme dicho la verdad antes.",hint:{sentenceWithBlank:"You [____] me the truth earlier.",options:[{text:"should have told",isCorrect:!0,explanation:"'Should + have + participio' sirve para reprochar algo que no se hizo en el pasado."},{text:"should tell",isCorrect:!1,explanation:"Se refiere al presente o al futuro."},{text:"must have told",isCorrect:!1,explanation:"Expresa una deducción segura: 'seguro que lo dijiste'."}]},tense:"Modal Verbs",topic:"General",lengthWords:8},{id:"59",text:"I could play the piano when I was a child.",translation:"Sabía tocar el piano cuando era niño.",hint:{sentenceWithBlank:"I [____] play the piano when I was a child.",options:[{text:"could",isCorrect:!0,explanation:"'Could' es el pasado de 'can' y expresa habilidades del pasado."},{text:"can",isCorrect:!1,explanation:"'Can' se refiere al presente."},{text:"must",isCorrect:!1,explanation:"'Must' expresa obligación, no capacidad física."}]},tense:"Modal Verbs",topic:"General",lengthWords:10},{id:"60",text:"We had better leave now before it gets dark.",translation:"Más vale que nos vayamos ya, antes de que anochezca.",hint:{sentenceWithBlank:"We [____] leave now before it gets dark.",options:[{text:"had better",isCorrect:!0,explanation:"'Had better' (más vale que) expresa consejos enérgicos o advertencias."},{text:"would rather",isCorrect:!1,explanation:"'Would rather' expresa preferencia (preferiría)."},{text:"should to",isCorrect:!1,explanation:"Detrás de 'should' no se pone la partícula 'to'."}]},tense:"Modal Verbs",topic:"General",lengthWords:9},{id:"61",text:"If you heat ice, it melts.",translation:"Si calientas el hielo, se derrite.",hint:{sentenceWithBlank:"If you heat ice, it [____].",options:[{text:"melts",isCorrect:!0,explanation:"En el Zero Conditional (verdades generales) las dos partes van en Present Simple."},{text:"will melt",isCorrect:!1,explanation:"Para los hechos científicos se usa el presente, no el futuro."},{text:"melted",isCorrect:!1,explanation:"El pasado no encaja aquí."}]},tense:"Conditionals",topic:"Science",lengthWords:6},{id:"62",text:"If I have time tonight, I will call you.",translation:"Si tengo tiempo esta noche, te llamaré.",hint:{sentenceWithBlank:"If I [____] time tonight, I [____] you.",options:[{text:"have / will call",isCorrect:!0,explanation:"First Conditional: la condición en Present Simple (have) y el resultado en Future Simple (will call)."},{text:"will have / call",isCorrect:!1,explanation:"Detrás de 'if' no se usa el futuro (will) en la condición."},{text:"had / would call",isCorrect:!1,explanation:"Es el Second Conditional para situaciones irreales, pero aquí la condición es real."}]},tense:"Conditionals",topic:"General",lengthWords:9},{id:"63",text:"Unless you study hard, you won't pass the exam.",translation:"Si no estudias mucho, no aprobarás el examen.",hint:{sentenceWithBlank:"[____] you study hard, you won't pass the exam.",options:[{text:"Unless",isCorrect:!0,explanation:"'Unless' equivale a 'si no' (if not) y ya lleva la negación incorporada."},{text:"If",isCorrect:!1,explanation:"Con 'if' quedaría 'si estudias, no aprobarás', lo cual no tiene sentido."},{text:"Without",isCorrect:!1,explanation:"'Without' es una preposición (sin) y pide detrás un sustantivo o un gerundio."}]},tense:"Conditionals",topic:"Education",lengthWords:9},{id:"64",text:"As soon as I arrive, I will let you know.",translation:"En cuanto llegue, te aviso.",hint:{sentenceWithBlank:"[____] I arrive, I will let you know.",options:[{text:"As soon as",isCorrect:!0,explanation:"'As soon as' (en cuanto) introduce oraciones temporales con Present Simple."},{text:"Until",isCorrect:!1,explanation:"'Until' significa 'hasta que' y cambia el sentido de la frase."},{text:"While",isCorrect:!1,explanation:"'While' (mientras) se usa con procesos prolongados."}]},tense:"Conditionals",topic:"General",lengthWords:10},{id:"65",text:"If I won the lottery, I would buy a house by the sea.",translation:"Si me tocara la lotería, me compraría una casa junto al mar.",hint:{sentenceWithBlank:"If I [____] the lottery, I [____] a house by the sea.",options:[{text:"won / would buy",isCorrect:!0,explanation:"Second Conditional: condición en Past Simple (won) y resultado con would + infinitivo."},{text:"win / would buy",isCorrect:!1,explanation:"'Win' en presente no concuerda con el 'would' de la oración principal."},{text:"won / will buy",isCorrect:!1,explanation:"Tras un Past Simple en la condición se usa 'would', no 'will'."}]},tense:"Conditionals",topic:"General",lengthWords:13},{id:"66",text:"What would you do if you were in my shoes?",translation:"¿Qué harías tú en mi lugar?",hint:{sentenceWithBlank:"What [____] if you [____] in my shoes?",options:[{text:"would you do / were",isCorrect:!0,explanation:"Second Conditional: 'would + infinitivo' en la pregunta y 'were' para todas las personas en la condición."},{text:"will you do / are",isCorrect:!1,explanation:"Es el First Conditional, pero 'in my shoes' plantea una situación hipotética."},{text:"do you do / was",isCorrect:!1,explanation:"Gramática incorrecta para el condicional de segundo tipo."}]},tense:"Conditionals",topic:"General",lengthWords:10},{id:"67",text:"If I had more free time, I would take up photography.",translation:"Si tuviera más tiempo libre, me dedicaría a la fotografía.",hint:{sentenceWithBlank:"If I [____] more free time, I [____] take up photography.",options:[{text:"had / would",isCorrect:!0,explanation:"Second Conditional: condición irreal en el presente (had) y resultado con 'would'."},{text:"have / will",isCorrect:!1,explanation:"Expresa una condición real, pero aquí se subraya que la situación es irreal."},{text:"had had / would have",isCorrect:!1,explanation:"Es el Third Conditional y se refiere al pasado."}]},tense:"Conditionals",topic:"General",lengthWords:11},{id:"68",text:"If we had left earlier, we wouldn't have missed the flight.",translation:"Si hubiéramos salido antes, no habríamos perdido el vuelo.",hint:{sentenceWithBlank:"If we [____] earlier, we [____] the flight.",options:[{text:"had left / wouldn't have missed",isCorrect:!0,explanation:"Third Conditional: condición irreal en pasado (Past Perfect) y resultado pasado (would have + participio)."},{text:"left / wouldn't miss",isCorrect:!1,explanation:"Es el Second Conditional y se refiere al presente, no a un pasado cerrado."},{text:"had left / wouldn't miss",isCorrect:!1,explanation:"Sería un condicional mixto, que no encaja porque ambas acciones están en el pasado."}]},tense:"Conditionals",topic:"Travel",lengthWords:11},{id:"69",text:"I wouldn't have known about the project if you hadn't told me.",translation:"No me habría enterado del proyecto si no me lo hubieras contado.",hint:{sentenceWithBlank:"I wouldn't [____] about the project if you hadn't told me.",options:[{text:"have known",isCorrect:!0,explanation:"Third Conditional: la oración principal se forma con 'would have + participio' para el pasado."},{text:"know",isCorrect:!1,explanation:"'Wouldn't know' se referiría al presente."},{text:"knew",isCorrect:!1,explanation:"Tras 'would have' va el participio (known), no la segunda forma."}]},tense:"Conditionals",topic:"General",lengthWords:12},{id:"70",text:"If I had studied harder at university, I would have a better job now.",translation:"Si hubiera estudiado más en la universidad, ahora tendría un trabajo mejor.",hint:{sentenceWithBlank:"If I [____] harder at university, I [____] a better job now.",options:[{text:"had studied / would have",isCorrect:!0,explanation:"Condicional mixto: condición en el pasado (Past Perfect) y consecuencia en el presente (would + infinitivo)."},{text:"studied / would have",isCorrect:!1,explanation:"La etapa universitaria ya pasó, así que hace falta el Past Perfect."},{text:"had studied / would have had",isCorrect:!1,explanation:"La consecuencia es actual (now), por eso 'would have' y no 'would have had'."}]},tense:"Conditionals",topic:"Education",lengthWords:14},{id:"71",text:"If he spoke French, he would have translated that document yesterday.",translation:"Si hablara francés, habría traducido aquel documento ayer.",hint:{sentenceWithBlank:"If he [____] French, he [____] that document yesterday.",options:[{text:"spoke / would have translated",isCorrect:!0,explanation:"Condicional mixto: condición permanente (Past Simple) y consecuencia pasada (would have + participio)."},{text:"had spoken / would translate",isCorrect:!1,explanation:"Saber un idioma es un hecho permanente, mientras que la traducción fue ayer."},{text:"spoke / would translate",isCorrect:!1,explanation:"La traducción se sitúa ayer (yesterday), así que hace falta 'would have + participio'."}]},tense:"Conditionals",topic:"Workplace",lengthWords:11},{id:"72",text:"I wish I had more money.",translation:"Ojalá tuviera más dinero.",hint:{sentenceWithBlank:"I [____] I [____] more money.",options:[{text:"wish / had",isCorrect:!0,explanation:"La estructura 'I wish + Past Simple' expresa lamento por una situación presente."},{text:"wish / have",isCorrect:!1,explanation:"Tras 'I wish', para hablar del presente se usa el Past Simple."},{text:"hope / had",isCorrect:!1,explanation:"Después de 'hope' se emplean tiempos reales (presente o futuro)."}]},tense:"Conditionals",topic:"General",lengthWords:6},{id:"73",text:"I wish you wouldn't make so much noise.",translation:"Ojalá no hicieras tanto ruido.",hint:{sentenceWithBlank:"I wish you [____] make so much noise.",options:[{text:"wouldn't",isCorrect:!0,explanation:"'I wish + would/wouldn't' expresa fastidio por el comportamiento de otra persona."},{text:"don't",isCorrect:!1,explanation:"Después de 'I wish' no se usa el Present Simple."},{text:"didn't",isCorrect:!1,explanation:"'Didn't' sería posible, pero 'wouldn't' expresa mejor el fastidio por la conducta ajena."}]},tense:"Conditionals",topic:"General",lengthWords:8},{id:"74",text:"If only I hadn't said that to her yesterday.",translation:"Ojalá no le hubiera dicho eso ayer.",hint:{sentenceWithBlank:"If [____] I [____] said that to her yesterday.",options:[{text:"only / hadn't",isCorrect:!0,explanation:"'If only + Past Perfect' expresa un fuerte arrepentimiento por el pasado."},{text:"only / didn't",isCorrect:!1,explanation:"La acción fue ayer, así que hace falta el Past Perfect y no el Past Simple."},{text:"just / haven't",isCorrect:!1,explanation:"'If just' no existe, y 'haven't' es Present Perfect, incompatible con 'yesterday'."}]},tense:"Conditionals",topic:"General",lengthWords:9},{id:"75",text:"It's time we went home.",translation:"Ya es hora de que nos vayamos a casa.",hint:{sentenceWithBlank:"It's time we [____] home.",options:[{text:"went",isCorrect:!0,explanation:"Tras la estructura 'It's time' se usa la forma de Past Simple."},{text:"go",isCorrect:!1,explanation:"Con 'It's time + sujeto' el verbo va en Past Simple, no en infinitivo."},{text:"are going",isCorrect:!1,explanation:"El presente continuo no se emplea en esta estructura."}]},tense:"Conditionals",topic:"General",lengthWords:5},{id:"76",text:"This house was built in 1920.",translation:"Esta casa fue construida en 1920.",hint:{sentenceWithBlank:"This house [____] in 1920.",options:[{text:"was built",isCorrect:!0,explanation:"La pasiva en pasado (Past Simple Passive) señala una acción hecha sobre el objeto en el pasado."},{text:"built",isCorrect:!1,explanation:"Aquí hace falta la pasiva, porque la casa no se construyó a sí misma."},{text:"is built",isCorrect:!1,explanation:"La acción ocurrió en el pasado (en 1920), así que se necesita un tiempo pasado."}]},tense:"Passive Voice",topic:"General",lengthWords:6},{id:"77",text:"The interface is being redesigned at the moment.",translation:"La interfaz se está rediseñando en este momento.",hint:{sentenceWithBlank:"The interface [____] at the moment.",options:[{text:"is being redesigned",isCorrect:!0,explanation:"La pasiva del Present Continuous expresa lo que se está haciendo justo ahora (at the moment)."},{text:"is redesigned",isCorrect:!1,explanation:"La pasiva del Present Simple indica una acción habitual, no algo en curso."},{text:"has been redesigned",isCorrect:!1,explanation:"Es la pasiva del Present Perfect: una acción ya terminada."}]},tense:"Passive Voice",topic:"IT",lengthWords:8},{id:"78",text:"The new software has just been installed.",translation:"El nuevo software acaba de instalarse.",hint:{sentenceWithBlank:"The new software [____].",options:[{text:"has just been installed",isCorrect:!0,explanation:"La pasiva del Present Perfect expresa una acción recién terminada (con 'just')."},{text:"has just installed",isCorrect:!1,explanation:"El software no puede instalarse a sí mismo: hace falta la voz pasiva."},{text:"was just installed",isCorrect:!1,explanation:"Con el adverbio 'just' se prefiere el Present Perfect antes que el Past Simple."}]},tense:"Passive Voice",topic:"IT",lengthWords:7},{id:"79",text:"English is spoken all over the world.",translation:"El inglés se habla en todo el mundo.",hint:{sentenceWithBlank:"English [____] all over the world.",options:[{text:"is spoken",isCorrect:!0,explanation:"La pasiva del Present Simple sirve para hechos generales conocidos."},{text:"is speaking",isCorrect:!1,explanation:"Un idioma no habla por sí solo: hace falta la voz pasiva."},{text:"spoke",isCorrect:!1,explanation:"Es voz activa en pasado."}]},tense:"Passive Voice",topic:"General",lengthWords:7},{id:"80",text:"The letters will be sent tomorrow morning.",translation:"Las cartas se enviarán mañana por la mañana.",hint:{sentenceWithBlank:"The letters [____] tomorrow morning.",options:[{text:"will be sent",isCorrect:!0,explanation:"La pasiva del Future Simple expresa una acción futura sobre el objeto."},{text:"will send",isCorrect:!1,explanation:"Las cartas no pueden enviarse solas (hace falta la pasiva)."},{text:"are sent",isCorrect:!1,explanation:"Es la pasiva del Present Simple, pero la acción ocurrirá mañana."}]},tense:"Passive Voice",topic:"General",lengthWords:7},{id:"81",text:"I need to get my hair cut this week.",translation:"Necesito cortarme el pelo esta semana.",hint:{sentenceWithBlank:"I need to [____] this week.",options:[{text:"get my hair cut",isCorrect:!0,explanation:"La estructura 'get/have something done' indica que otra persona hace la acción por ti."},{text:"cut my hair",isCorrect:!1,explanation:"Significaría que te cortas el pelo tú mismo."},{text:"get cutting my hair",isCorrect:!1,explanation:"Construcción gramaticalmente incorrecta."}]},tense:"Passive Voice",topic:"Daily Life",lengthWords:9},{id:"82",text:"He had his laptop stolen while he was traveling.",translation:"Le robaron el portátil mientras viajaba.",hint:{sentenceWithBlank:"He [____] while he was traveling.",options:[{text:"had his laptop stolen",isCorrect:!0,explanation:"La estructura 'have something done' también sirve para experiencias negativas (alguien le robó el portátil)."},{text:"stole his laptop",isCorrect:!1,explanation:"Significaría que él mismo robó su portátil."},{text:"had stolen his laptop",isCorrect:!1,explanation:"Es Past Perfect en voz activa: él había robado su portátil antes de cierto momento."}]},tense:"Passive Voice",topic:"General",lengthWords:9},{id:"83",text:"She was made to clean the whole room by her mother.",translation:"Su madre la obligó a limpiar toda la habitación.",hint:{sentenceWithBlank:"She [____] to clean the whole room by her mother.",options:[{text:"was made",isCorrect:!0,explanation:"En voz pasiva, el verbo 'make' con el sentido de obligar exige la partícula 'to' delante del siguiente verbo."},{text:"made",isCorrect:!1,explanation:"La voz activa cambiaría el sentido: 'ella obligó'."},{text:"has made",isCorrect:!1,explanation:"También es voz activa, pero en Present Perfect."}]},tense:"Passive Voice",topic:"Daily Life",lengthWords:11},{id:"84",text:"He is said to be the richest man in the city.",translation:"Dicen que es el hombre más rico de la ciudad.",hint:{sentenceWithBlank:"He [____] to be the richest man in the city.",options:[{text:"is said",isCorrect:!0,explanation:"La estructura pasiva 'is said to' equivale a 'se dice que él...'."},{text:"says",isCorrect:!1,explanation:"Significaría 'Él dice que es el más rico...'."},{text:"said",isCorrect:!1,explanation:"El pasado 'Él dijo' rompe la estructura de la frase."}]},tense:"Passive Voice",topic:"General",lengthWords:11},{id:"85",text:"It is expected that the prices will drop soon.",translation:"Se espera que los precios bajen pronto.",hint:{sentenceWithBlank:"[____] that the prices will drop soon.",options:[{text:"It is expected",isCorrect:!0,explanation:"La construcción pasiva impersonal expresa una opinión o una expectativa general."},{text:"It expects",isCorrect:!1,explanation:"'It' no puede 'esperar' nada: hace falta la pasiva."},{text:"They is expected",isCorrect:!1,explanation:"Es incorrecto: con 'They' iría 'are', pero aquí se necesita el impersonal 'It'."}]},tense:"Passive Voice",topic:"General",lengthWords:9},{id:"86",text:"He said that he was working on a new project.",translation:"Dijo que estaba trabajando en un proyecto nuevo.",hint:{sentenceWithBlank:"He said that he [____] on a new project.",options:[{text:"was working",isCorrect:!0,explanation:"Por la concordancia de tiempos, el Present Continuous del estilo directo pasa a Past Continuous."},{text:"is working",isCorrect:!1,explanation:"Como la oración principal está en pasado ('said'), la subordinada debe concordar."},{text:"works",isCorrect:!1,explanation:"Indica una acción permanente (Present Simple) y rompe la concordancia de tiempos."}]},tense:"Reported Speech",topic:"Workplace",lengthWords:10},{id:"87",text:"She told me she had already seen that movie.",translation:"Me dijo que ya había visto esa película.",hint:{sentenceWithBlank:"She [____] me she had already seen that movie.",options:[{text:"told",isCorrect:!0,explanation:"El verbo 'tell' siempre pide un complemento de persona (a quién se lo dijeron: 'me')."},{text:"said",isCorrect:!1,explanation:"Tras 'said' hace falta la preposición 'to' si se menciona al destinatario: 'said to me'."},{text:"spoke",isCorrect:!1,explanation:"'Speak' significa hablar un idioma o conversar con alguien; no introduce el estilo indirecto."}]},tense:"Reported Speech",topic:"Entertainment",lengthWords:9},{id:"88",text:"They said they would help us the following week.",translation:"Dijeron que nos ayudarían la semana siguiente.",hint:{sentenceWithBlank:"They said they [____] help us the following week.",options:[{text:"would",isCorrect:!0,explanation:"En la concordancia de tiempos, 'will' se transforma en 'would'."},{text:"will",isCorrect:!1,explanation:"Rompe la regla de concordancia, ya que la oración principal está en pasado."},{text:"should",isCorrect:!1,explanation:"Cambiaría el sentido a 'deberían ayudar' en lugar de una simple acción futura."}]},tense:"Reported Speech",topic:"General",lengthWords:9},{id:"89",text:"He asked me where I lived.",translation:"Me preguntó dónde vivía.",hint:{sentenceWithBlank:"He asked me where [____].",options:[{text:"I lived",isCorrect:!0,explanation:"En las preguntas indirectas se usa el orden de la afirmación y se aplica la concordancia de tiempos."},{text:"did I live",isCorrect:!1,explanation:"No hace falta auxiliar, porque es una pregunta indirecta y no directa."},{text:"I live",isCorrect:!1,explanation:"Rompe la concordancia de tiempos (la oración principal está en pasado: asked)."}]},tense:"Reported Speech",topic:"General",lengthWords:6},{id:"90",text:"She asked if I could help her with the task.",translation:"Me preguntó si podía ayudarla con la tarea.",hint:{sentenceWithBlank:"She asked [____] I could help her with the task.",options:[{text:"if",isCorrect:!0,explanation:"En estilo indirecto, las preguntas generales (sin partícula interrogativa) se introducen con 'if' o 'whether'."},{text:"that",isCorrect:!1,explanation:"'That' introduce afirmaciones, no preguntas."},{text:"can",isCorrect:!1,explanation:"No encaja en esta estructura gramatical."}]},tense:"Reported Speech",topic:"General",lengthWords:10},{id:"91",text:"The manager advised me to review the guidelines.",translation:"El jefe me aconsejó que revisara las directrices.",hint:{sentenceWithBlank:"The manager advised me [____] the guidelines.",options:[{text:"to review",isCorrect:!0,explanation:"Tras verbos como 'advise', 'ask' o 'tell' se usa el infinitivo con 'to'."},{text:"reviewing",isCorrect:!1,explanation:"El gerundio no se usa detrás de 'advise' + persona."},{text:"review",isCorrect:!1,explanation:"Falta la partícula 'to', necesaria para el infinitivo."}]},tense:"Reported Speech",topic:"Workplace",lengthWords:8},{id:"92",text:"He denied making that mistake.",translation:"Negó haber cometido ese error.",hint:{sentenceWithBlank:"He denied [____] that mistake.",options:[{text:"making",isCorrect:!0,explanation:"Detrás del verbo 'deny' se usa el gerundio (V-ing)."},{text:"to make",isCorrect:!1,explanation:"'Deny' no admite el infinitivo."},{text:"make",isCorrect:!1,explanation:"Forma gramaticalmente incorrecta."}]},tense:"Reported Speech",topic:"General",lengthWords:5},{id:"93",text:"She promised not to tell anyone his secret.",translation:"Prometió no contarle a nadie su secreto.",hint:{sentenceWithBlank:"She promised [____] anyone his secret.",options:[{text:"not to tell",isCorrect:!0,explanation:"El infinitivo negativo se forma poniendo 'not' delante de 'to'."},{text:"to not tell",isCorrect:!1,explanation:"Orden de palabras poco correcto según la gramática estándar."},{text:"don't tell",isCorrect:!1,explanation:"Aquí hace falta un infinitivo, no un imperativo."}]},tense:"Reported Speech",topic:"General",lengthWords:8},{id:"94",text:"Although it was raining, we went for a walk.",translation:"Aunque llovía, salimos a pasear.",hint:{sentenceWithBlank:"[____] it was raining, we went for a walk.",options:[{text:"Although",isCorrect:!0,explanation:"La conjunción 'although' (aunque) va seguida de sujeto y verbo."},{text:"Despite",isCorrect:!1,explanation:"Detrás de 'despite' debe ir un sustantivo o un gerundio, no una oración completa (it was raining)."},{text:"However",isCorrect:!1,explanation:"Suele funcionar como conector y va separado por comas."}]},tense:"Conjunctions",topic:"General",lengthWords:9},{id:"95",text:"Despite the heavy traffic, we arrived on time.",translation:"A pesar del mucho tráfico, llegamos a tiempo.",hint:{sentenceWithBlank:"[____] the heavy traffic, we arrived on time.",options:[{text:"Despite",isCorrect:!0,explanation:"'Despite' (a pesar de) se usa con un sustantivo o un gerundio."},{text:"Although",isCorrect:!1,explanation:"Detrás de 'although' debe ir una oración completa (sujeto + verbo)."},{text:"In spite",isCorrect:!1,explanation:"Necesita la preposición 'of' (In spite of)."}]},tense:"Conjunctions",topic:"Travel",lengthWords:8},{id:"96",text:"Seldom have I seen such a beautiful piece of art.",translation:"Pocas veces he visto una obra de arte tan bonita.",hint:{sentenceWithBlank:"[____] such a beautiful piece of art.",options:[{text:"Seldom have I seen",isCorrect:!0,explanation:"Los adverbios negativos o restrictivos (seldom) al principio de la frase exigen la inversión."},{text:"Seldom I have seen",isCorrect:!1,explanation:"Tras 'seldom' en posición inicial hace falta la inversión (orden de pregunta)."},{text:"Have I seldom seen",isCorrect:!1,explanation:"El adverbio 'seldom' debe ir en primer lugar."}]},tense:"Inversion",topic:"General",lengthWords:10},{id:"97",text:"No sooner had I closed the door than the phone rang.",translation:"Nada más cerrar la puerta, sonó el teléfono.",hint:{sentenceWithBlank:"[____] closed the door than the phone rang.",options:[{text:"No sooner had I",isCorrect:!0,explanation:"La estructura 'No sooner + inversión (had I) ... than' equivale a 'nada más..., cuando...'."},{text:"No sooner I had",isCorrect:!1,explanation:"Tras 'No sooner' es obligatoria la inversión del auxiliar y el sujeto."},{text:"As soon as I had",isCorrect:!1,explanation:"'As soon as' no se combina con 'than' en la segunda parte de la frase."}]},tense:"Inversion",topic:"General",lengthWords:11},{id:"98",text:"I look forward to hearing from you soon.",translation:"Espero con interés tener noticias suyas pronto.",hint:{sentenceWithBlank:"I look forward [____] from you soon.",options:[{text:"to hearing",isCorrect:!0,explanation:"En 'look forward to', 'to' es una preposición, así que detrás va un gerundio (V-ing)."},{text:"to hear",isCorrect:!1,explanation:"Aquí 'to' no forma parte del infinitivo, sino que es una preposición: hace falta el gerundio."},{text:"hearing",isCorrect:!1,explanation:"Falta la preposición 'to', que es obligatoria."}]},tense:"Gerund",topic:"Workplace",lengthWords:8},{id:"99",text:"It's no use crying over spilled milk.",translation:"A lo hecho, pecho. / De nada sirve llorar sobre la leche derramada.",hint:{sentenceWithBlank:"It's no use [____] over spilled milk.",options:[{text:"crying",isCorrect:!0,explanation:"Tras la expresión 'it's no use' (de nada sirve) siempre va un gerundio."},{text:"to cry",isCorrect:!1,explanation:"El infinitivo no se usa en esta expresión idiomática."},{text:"cry",isCorrect:!1,explanation:"Forma gramaticalmente incorrecta: hace falta el gerundio."}]},tense:"Gerund",topic:"General",lengthWords:7},{id:"100",text:"Not only did he design the layout, but he also wrote the code.",translation:"No solo diseñó la maqueta, sino que además escribió el código.",hint:{sentenceWithBlank:"Not only [____] the layout, but he also wrote the code.",options:[{text:"did he design",isCorrect:!0,explanation:"Cuando la frase empieza por 'Not only', se aplica la inversión (orden de pregunta)."},{text:"he designed",isCorrect:!1,explanation:"Falta la inversión, obligatoria tras 'Not only' en posición inicial."},{text:"designed he",isCorrect:!1,explanation:"La inversión se hace con el auxiliar 'did', no con el verbo principal."}]},tense:"Inversion",topic:"IT",lengthWords:13}]};export{e as builtInPack};
